APP_NAME         = "Siril Wizard – Automatic Multi-Session Processing"
VERSION          = "1.0.11"
FITS_SUFFIXES    = {'.fits', '.fit', '.fts'}
FITS_FZ_SUFFIXES = {'.fits.fz', '.fit.fz', '.fts.fz'}
FITS_EXTS      = tuple(FITS_SUFFIXES | FITS_FZ_SUFFIXES)
def _default_config_path() -> Path:
    """Return the platform-appropriate config path for the script."""
    if sys.platform == 'win32':
        base = Path(os.environ.get('LOCALAPPDATA', Path.home() / 'AppData' / 'Local'))
        return base / 'siril' / 'amsp.json'
    elif sys.platform == 'darwin':
        return Path.home() / 'Library' / 'Application Support' / 'org.Siril.siril' / 'siril' / 'amsp.json'
    else:  # Linux and other Unix
        return Path.home() / '.config' / 'siril' / 'amsp.json'

CONFIG_PATH      = _default_config_path()

NO_FILTER        = '—'

STACK_SAVE_PATTERN = (
    '$OBJECT:%s$_$FILTER:%s$_$STACKCNT:%d$x$EXPTIME:%d$'
    'sec_G$GAIN:%d$_O$OFFSET:%d$_T$CCD-TEMP:%d$C_$DATE-OBS:dm12$'
)

TYPE_INFO: dict[str, tuple[str, str]] = {
    'light':   ('💡  Lights',  '#5BA3FF'),
    'flat':    ('🌓  Flats',   '#FFB347'),
    'dark':    ('🌑  Darks',   '#BBBBBB'),
    'bias':    ('⚡  Bias',    '#CC99FF'),
    'unknown': ('❓  Unknown', '#FF7070'),
}
TYPE_ORDER        = ['light', 'flat', 'dark', 'bias', 'unknown']
TYPES_WITH_FILTER = {'light', 'flat'}
SUB_INFO          = ('📷  Subs',    '#CCCCCC')
MASTER_INFO       = ('🏆  Masters', '#FFD700')

PHASE_LABELS = [
    'Master Bias',
    'Master Darks',
    'Master Flats',
    'Calibrate Lights',
    'Register & Stack',
    'Cross-stack Alignment',
]
N_PHASES = len(PHASE_LABELS)

# Instruments / capture apps known to omit the IMAGETYP keyword.
# Detection scans the TELESCOP / INSTRUME / ORIGIN headers (case-insensitive
# substring match). Add a new tag here when another such device is encountered.
INSTRUMENTS_WITHOUT_IMAGETYP: tuple[str, ...] = (
    'DWARF',     # DWARF 3 / DWARFLAB
)

# =============================================================================
# Utility functions
# =============================================================================

def is_fits_file(p: Path) -> bool:
    name = p.name.lower()
    return any(name.endswith(ext) for ext in FITS_EXTS)


def _qflag(flag: str, path) -> str:
    """Build a Siril flag argument, quoting the ENTIRE token when path has spaces.
    Siril syntax: command "-flag=my path/file.fit"  (not -flag="my path/file.fit")
    """
    p = str(Path(path).resolve())
    return f'"{flag}={p}"' if ' ' in p else f'{flag}={p}'


def _qarg(path) -> str:
    """Quote a standalone path argument when it contains spaces."""
    p = str(Path(path).resolve())
    return f'"{p}"' if ' ' in p else p


def _safe_name(filt: str) -> str:
    """Sanitise a string for use in directory and sequence names.

    Replaces or strips characters that are problematic on any OS or
    that would break Siril command parsing (apostrophes, quotes, etc.).
    """
    import re
    safe = (filt
            .replace(NO_FILTER, 'nofilter')
            # Apostrophes / quotes break shell-like command parsing
            .replace("'", '').replace('"', '')
            # Separators → underscore
            .replace('/', '_').replace('\\', '_')
            .replace(' ', '_').replace('-', '_')
            # Remove any remaining non-alphanumeric except underscore and dot
            )
    safe = re.sub(r'[^\w.]', '', safe)
    # Collapse multiple underscores
    safe = re.sub(r'_+', '_', safe).strip('_')
    return safe or 'unnamed'


def _exptime_key(exptime) -> str:
    """
    Round an exposure time to a filesystem-safe string.
    600.0 → '600s', 1.5 → '1s', None → 'Xs'
    """
    if exptime is None:
        return 'Xs'
    return f'{round(exptime):d}s'


def _exptime_sort_key(exp_str: str) -> float:
    """
    Numeric sort key for strings produced by _exptime_key.
    Sorts '1s' < '30s' < '600s' < 'Xs' (unknowns last).
    """
    if exp_str == 'Xs':
        return float('inf')
    try:
        return float(exp_str.rstrip('s'))
    except ValueError:
        return float('inf')

def normalize_imagetyp(raw: str) -> str:
    t = raw.strip().lower()
    if 'light' in t or t == 'science': return 'light'
    if 'flat'  in t:                   return 'flat'
    if 'dark'  in t:                   return 'dark'
    if 'bias'  in t or 'zero' in t:    return 'bias'
    return 'unknown'

def _instrument_omits_imagetyp(h) -> bool:
    """True if the header was produced by a device known to skip IMAGETYP."""
    blob = ' '.join(
        str(h.get(k, '')) for k in ('TELESCOP', 'INSTRUME', 'ORIGIN')
    ).upper()
    return any(tag in blob for tag in INSTRUMENTS_WITHOUT_IMAGETYP)


def _infer_imgtype_from_content(h) -> str:
    """
    Fallback IMAGETYP inference for capture devices that don't write the
    keyword. Uses FILTER / OBJECT / RA / DEC only:
      - dark : empty FILTER & OBJECT, RA≈0 and DEC≈0
      - light: a FILTER value AND an OBJECT name
    Bias and flat are not inferred (no reliable signal in observed headers).
    Returns 'dark', 'light' or 'unknown'.
    """
    flt = str(h.get('FILTER', '')).strip()
    obj = str(h.get('OBJECT', '')).strip()
    try:
        ra  = float(h.get('RA',  0) or 0)
        dec = float(h.get('DEC', 0) or 0)
    except (ValueError, TypeError):
        ra, dec = 0.0, 0.0

    if not flt and not obj and abs(ra) < 1e-6 and abs(dec) < 1e-6:
        return 'dark'
    if flt and obj:
        return 'light'
    return 'unknown'

def night_key(date_obs: str) -> str:
    """Noon-to-noon observation night as YYYY-MM-DD."""
    try:
        dt = datetime.fromisoformat(date_obs.replace('Z', ''))
        return (dt - timedelta(hours=12)).strftime('%Y-%m-%d')
    except Exception:
        return '????-??-??'


def collect_fits(paths: list[str]) -> list[Path]:
    """Recursively collect deduplicated FITS files from file/folder paths."""
    found: list[Path] = []
    for p in paths:
        pp = Path(p)
        if pp.is_dir():
            for f in pp.rglob('*'):
                if f.is_file() and is_fits_file(f):
                    found.append(f)
        elif pp.is_file() and is_fits_file(pp):
            found.append(pp)
    seen, unique = set(), []
    for f in found:
        key = f.resolve()
        if key not in seen:
            seen.add(key)
            unique.append(f)
    return unique


def _find_image_header(hdul):
    """
    Return the header containing IMAGETYP.
    Plain FITS → HDU[0]. Rice-compressed .fits.fz → HDU[0] is a stub,
    real keywords live in the CompImageHDU (HDU[1]).
    """
    for hdu in hdul:
        if 'IMAGETYP' in hdu.header:
            return hdu.header
    return hdul[0].header


def read_fits_info(path: Path) -> dict:
    """Read all relevant metadata from a FITS header via astropy."""
    info: dict = {
        'path':        path,
        'name':        path.name,
        'imgtype':     'unknown',
        'filter':      NO_FILTER,
        'date_obs':    '',
        'session':     '????-??-??',
        'is_master':   False,
        'stackcnt':    0,
        'exptime':     None,
        'object_name': '',
        'bayerpat':    None,    # str if CFA, None if mono
        'instrume':    '',
        'width':       0,
        'height':      0,
    }
    try:
        with astrofits.open(path, memmap=True, ignore_missing_simple=True) as hdul:
            h = _find_image_header(hdul)
            info['imgtype'] = normalize_imagetyp(str(h.get('IMAGETYP', '')))
            # Some capture devices (e.g. DWARF 3) omit IMAGETYP — infer it
            # from FILTER / OBJECT / RA / DEC. See INSTRUMENTS_WITHOUT_IMAGETYP.
            if info['imgtype'] == 'unknown' and _instrument_omits_imagetyp(h):
                info['imgtype'] = _infer_imgtype_from_content(h)
            flt = str(h.get('FILTER', '')).strip()
            if not flt or flt.lower() in ('empty', 'none'):
                info['filter'] = NO_FILTER
            else:
                info['filter'] = flt
            dobs = str(h.get('DATE-OBS', '')).strip()
            if dobs:
                info['date_obs'] = dobs
                info['session']  = night_key(dobs)
            for kw in ('EXPTIME', 'EXPOSURE'):
                raw = h.get(kw, None)
                if raw is not None:
                    try:
                        info['exptime'] = float(raw); break
                    except (ValueError, TypeError):
                        pass
            obj = str(h.get('OBJECT', '')).strip()
            if obj and obj.lower() != 'flatwizard':
                info['object_name'] = obj
            # Master detection: STACKCNT present AND > 1
            # (Siril writes STACKCNT=1 on individual calibrated subs)
            # Bayer pattern – presence means it's a colour (CFA) image
            bp = str(h.get('BAYERPAT', '')).strip().upper()
            # Only set bayerpat when the sensor is truly a CFA:
            # absent, 'NONE' or 'INVALID' all mean monochrome.
            if bp and bp not in ('NONE', 'INVALID'):
                info['bayerpat'] = bp
            # Instrument – used to validate external dark masters
            instrume = str(h.get('INSTRUME', '')).strip()
            if instrume:
                info['instrume'] = instrume
            # Image dimensions (NAXIS1=width, NAXIS2=height)
            try:
                info['width']  = int(h.get('NAXIS1', 0))
                info['height'] = int(h.get('NAXIS2', 0))
            except (ValueError, TypeError):
                pass

            sc = h.get('STACKCNT', None)
            if sc is not None:
                try:
                    cnt = int(sc)
                    if cnt > 1:
                        info['is_master'] = True
                        info['stackcnt']  = cnt
                except (ValueError, TypeError):
                    pass
    except Exception:
        pass
    return info


# =============================================================================
# Background header-scan thread
# =============================================================================

class ScanThread(QThread):
    progress = pyqtSignal(int, int)
    result   = pyqtSignal(list)

    def __init__(self, files: list[Path]):
        super().__init__()
        self.files = files

    def run(self):
        results, total = [], len(self.files)
        for i, f in enumerate(self.files, 1):
            results.append(read_fits_info(f))
            self.progress.emit(i, total)
        self.result.emit(results)


# =============================================================================
# Preprocessing engine
# =============================================================================

class PreprocessingEngine:
    """
    Orchestrates the full Siril calibration pipeline.
    All Siril calls go through the passed SirilInterface instance.
    """

    def __init__(
        self,
        siril:          s.SirilInterface,
        all_infos:      list[dict],          # subs + masters
        wd:             Path,                # Siril working directory
        output_dir:     Path,                # where final stacks land
        synthetic_bias: str,                 # e.g. "=10*$OFFSET" or ""
        external_darks: Optional[Path],      # folder of pre-stacked darks
        use_bkg:          bool  = False,
        use_disto:        bool  = True,
        use_nearest_flat: bool  = False,
        keep_masters:     bool  = True,
        use_drizzle:      bool  = False,
        drizzle_scale:    float = 1.0,
        drizzle_pixfrac:  float = 1.0,
        progress_cb:     Optional[Callable] = None,
    ):
        self.siril           = siril
        self.wd              = wd
        self.output_dir      = output_dir
        # Temporary working tree lives in the output directory so Siril
        self.proc_dir        = output_dir / '_preproc'
        self.masters_dir     = self.proc_dir / 'masters'
        self.synthetic_bias  = synthetic_bias.strip()
        self.external_darks  = external_darks
        self.use_bkg          = use_bkg
        self.use_disto        = use_disto
        self.use_nearest_flat  = use_nearest_flat
        self.keep_masters      = keep_masters
        self.saved_masters_dir = self.output_dir / 'masters'
        self.use_drizzle      = use_drizzle
        self.drizzle_scale    = drizzle_scale
        self.drizzle_pixfrac  = drizzle_pixfrac
        # Track master flat paths (needed for drizzle -flat= arg);
        # populated in _phase_flats before masters_dir is cleaned up.
        self._master_flats: dict = {}  # filt_safe → Path
        self.progress_cb     = progress_cb

        # Separate subs from pre-existing masters (user-dropped)
        self._subs    = [fi for fi in all_infos if not fi['is_master']]
        self._pre_masters = [fi for fi in all_infos if fi['is_master']]

        # Group subs: session → imgtype → filter → [dicts]
        self._by: dict = defaultdict(lambda: defaultdict(lambda: defaultdict(list)))
        for fi in self._subs:
            self._by[fi['session']][fi['imgtype']][fi['filter']].append(fi)

        self.sessions = sorted(self._by.keys())

        # Determine OBJECT name from first light sub
        self.object_name = 'lights'
        for fi in self._subs:
            if fi['imgtype'] == 'light' and fi.get('object_name'):
                self.object_name = (fi['object_name']
                                    .replace(' ', '_').replace('/', '_'))
                break

        # Instrument name – used to validate external darks compatibility
        self.instrument = ''
        for fi in self._subs:
            if fi.get('instrume'):
                self.instrument = fi['instrume']
                break

    # ── Low-level helpers ─────────────────────────────────────────────────────

    def _log(self, msg: str, color=LogColor.BLUE):
        self.siril.log(msg, color)

    def _cd(self, path: Path):
        path.mkdir(parents=True, exist_ok=True)
        _p = str(path.resolve())
        self.siril.cmd(f'cd "{_p}"' if ' ' in _p else f'cd {_p}')

    def _copy_files(self, files: list[dict], dest: Path):
        """
        Hard-copy source files into dest (never symlinks).
        Filename collisions (same name from different source dirs) are resolved
        by inserting a counter suffix before the extension.
        """
        dest.mkdir(parents=True, exist_ok=True)
        name_counters: dict[str, int] = {}
        for fi in files:
            src  = fi['path'].resolve()
            name = fi['name']
            original = name
            if name in name_counters:
                n = name_counters[name]
                name_lower = name.lower()
                # Try all known FITS extensions, longest first so that
                # '.fits.fz' is matched before '.fits'.
                for known_ext in sorted(FITS_EXTS, key=len, reverse=True):
                    if name_lower.endswith(known_ext):
                        stem = name[: len(name) - len(known_ext)]
                        name = f'{stem}_{n:03d}{known_ext}'
                        break
                name_counters[original] += 1
            else:
                name_counters[name] = 1
            dst = dest / name
            if not dst.exists():
                shutil.copy2(str(src), str(dst))

    def _get_active_requirements(self):
        """
        Returns:
            - active_filters: set of filters used by Lights
            - active_dark_exps: set of exposure keys (e.g., '300s', '2s') needed
              to calibrate both the Lights and the active Flats.
        """
        active_filters = set()
        active_dark_exps = set()
        active_flat_exps = set()

        # What do the LIGHTS need?
        for session in self.sessions:
            for filt_name, lights in self._by[session]['light'].items():
                if lights:
                    active_filters.add(filt_name)
                    # Lights need darks matching their own exposure
                    for li in lights:
                        active_dark_exps.add(_exptime_key(li['exptime']))

        # What do the FLATS need?
        # Only look at flats for filters we are actually using for lights
        for session in self.sessions:
            for filt_name, buckets in self._by[session]['flat'].items():
                if filt_name in active_filters:
                    for fi in buckets:
                        active_flat_exps.add(fi['exptime'])

        # If we don't have a Bias, we need Darks matching the Flat exposures
        if not self._bias_arg():
            for f_exp in active_flat_exps:
                active_dark_exps.add(_exptime_key(f_exp))

        return active_filters, active_dark_exps

    @staticmethod
    def _rejection_params(n: int) -> tuple[str, str, str]:
        """
        Choose stacking rejection algorithm and sigma values based on frame count.

          0–4   frames : percentile clipping  (p)  – very few frames, loose
          5–10  frames : sigma clipping        (s)
         11–30  frames : winsorized sigma      (w)
         31–300 frames : Generalized ESD       (g)
          301+  frames : linear-fit clipping   (l)

        Returns (algorithm_code, sigma_low, sigma_high).
        """
        if n <= 4:
            return 'p', '0.2', '0.1'
        elif n <= 10:
            return 's', '3', '3'
        elif n <= 30:
            return 'w', '3', '3'
        elif n <= 300:
            return 'g', '0.300', '0.050'
        else:
            return 'l', '5', '4'

    def _stack(self, seq: str, out: Path, norm: str = '-nonorm', n_frames: int = 0):
        """Stack *seq* with an automatically selected rejection algorithm."""
        algo, sig_lo, sig_hi = self._rejection_params(n_frames)
        self.siril.cmd(
            'stack', seq,
            'rej', algo, sig_lo, sig_hi,
            norm,
            _qflag('-out', out),
        )

    def _master_path(self, name: str) -> Path:
        return self.masters_dir / name

    def _save_master_if_needed(self, src: Path, imgtype: str,
                               session: str = '', filt: str = '',
                               exptime: str = '') -> None:
        """If keep_masters is on, copy src to output/masters/ with a descriptive name."""
        if not self.keep_masters or not src.exists():
            return
        self.saved_masters_dir.mkdir(parents=True, exist_ok=True)
        parts = [f'master-{imgtype}']
        if filt:    parts.append(_safe_name(filt))
        if exptime: parts.append(exptime)
        if session: parts.append(session)
        dest_name = '_'.join(parts) + '.fit'
        dest = self.saved_masters_dir / dest_name
        shutil.copy2(str(src), str(dest))
        self._log(f'  💾  Saved master: masters/{dest_name}', LogColor.BLUE)

    def _cleanup(self, path: Path):
        """Silently remove a directory tree (intermediate cleanup)."""
        if path.is_dir():
            shutil.rmtree(str(path), ignore_errors=True)
            try:
                label = path.relative_to(self.proc_dir)
            except ValueError:
                label = path
            self._log(f'  🗑  Removed: {label}', LogColor.BLUE)

    # ── Pre-existing master lookups ───────────────────────────────────────────

    def _find_pre_master(self, imgtype: str, session: str,
                         filt: Optional[str] = None) -> Optional[Path]:
        """
        Return the path of a user-dropped master for this imgtype/session
        (and filter if relevant). Returns None if not found.
        """
        for fi in self._pre_masters:
            if fi['imgtype'] != imgtype:
                continue
            if fi['session'] != session:
                continue
            if filt is not None and fi['filter'] != filt:
                continue
            return fi['path']
        return None

    def _ensure_master_in_dir(self, src: Path, dest_name: str) -> Path:
        """Copy a pre-existing master into masters_dir with the canonical name."""
        dest = self.masters_dir / dest_name
        if not dest.exists():
            shutil.copy2(str(src), str(dest))
        return dest

    # ── Bias / dark / flat argument builders ─────────────────────────────────

    def _bias_arg(self) -> Optional[str]:
        """Return the -bias= argument (or None).

        Priority:
          1. Synthetic bias expression (if set in UI) – skips all file lookup.
          2. Any master-bias file in masters_dir – most-recent file wins.
          3. None (no bias correction).
        """
        if self.synthetic_bias:
            return '-bias="' + self.synthetic_bias + '"'
        candidates: list[Path] = []
        for ext in FITS_EXTS:
            candidates.extend(self.masters_dir.glob(f'master-bias*{ext}'))
        if candidates:
            best = max(candidates, key=lambda p: p.stat().st_mtime)
            return _qflag('-bias', best)
        return None


    def _dark_flat_arg(self, flat_exptime: Optional[float]) -> Optional[str]:
        """
        Find a "dark flat" – a dark frame whose exposure time matches the
        flat's exposure time, used as -bias= when no real bias is available.

        Dark flats are stored as IMAGETYP=DARK by the capture software.
        They are searched in:
          1. masters_dir  (locally stacked master-dark_* files, read their EXPTIME header)
          2. external_darks folder (recursively, same as _dark_arg)

        The closest EXPTIME match within 20 % of the flat exptime is accepted.
        Returns a -bias=<path> argument string, or None.
        """
        if flat_exptime is None:
            return None

        best_path:  Optional[Path] = None
        best_delta: float          = float('inf')
        tolerance   = flat_exptime * 0.20  # 20 % tolerance

        def _check(f: Path):
            nonlocal best_path, best_delta
            if not is_fits_file(f):
                return
            try:
                with astrofits.open(f, memmap=True,
                                     ignore_missing_simple=True) as hdul:
                    h = _find_image_header(hdul)
                    imgtype = normalize_imagetyp(str(h.get('IMAGETYP', '')))
                    if imgtype != 'dark':
                        return
                    et = h.get('EXPTIME', h.get('EXPOSURE', None))
                    if et is None:
                        return
                    delta = abs(float(et) - flat_exptime)
                    if delta <= tolerance and delta < best_delta:
                        best_delta, best_path = delta, f
            except Exception:
                pass

        # 1. Locally stacked master-dark files in masters_dir
        for ext in FITS_EXTS:
            for p in self.masters_dir.glob(f'master-dark*{ext}'):
                _check(p)

        # 2. External darks folder
        if self.external_darks and self.external_darks.is_dir():
            for f in self.external_darks.rglob('*'):
                _check(f)

        if best_path is not None:
            self._log(
                f'    Using dark flat: {best_path.name}'
                f'  (ΔEXPTIME={best_delta:.2f}s, flat_exptime={flat_exptime:.0f}s)',
                LogColor.BLUE)
            return _qflag('-bias', best_path)
        return None

    def _dark_arg(self, session: str, exptime: Optional[float]) -> Optional[str]:
        """
        Choose the best master dark for the given exposure time.

        Dark frames depend on camera state (gain, offset, sensor temperature)
        rather than session date or filter, so any master dark with the
        right exposure can be reused across sessions.

        Selection order (when exptime is known):
          1. Exact exposure match anywhere in masters_dir.  All sessions are
             equivalent for darks – first match wins.
          2. Closest-exposure match across all session masters.  A warning
             is logged when the exposure delta exceeds 5 % of the target.
          3. Legacy generic master-dark_{session}.fit (no exptime suffix),
             retained for backwards compatibility.
          4. External darks folder – closest exposure match across all
             files, with INSTRUME mismatches filtered out.

        The 'session' argument is retained for the legacy fallback (step 3)
        and for log clarity, but does not affect the primary selection.
        """
        # ── Build the candidate list of in-folder per-exposure masters ───
        # Each entry: (path, file_session, file_et)
        candidates: list[tuple[Path, str, float]] = []
        prefix = 'master-dark_'
        for ext in FITS_EXTS:
            for p in self.masters_dir.glob(f'{prefix}*{ext}'):
                stem = p.name[: len(p.name) - len(ext)]
                rest = stem[len(prefix):]            # e.g. '2026-04-25_180s'
                if '_' not in rest:
                    continue                          # legacy generic name
                file_session, _, exp_token = rest.rpartition('_')
                if not exp_token.endswith('s'):
                    continue
                try:
                    file_et = float(exp_token[:-1])
                except ValueError:
                    continue
                candidates.append((p, file_session, file_et))

        if exptime is not None and candidates:
            target_key = _exptime_key(exptime)

            # 1. Exact exposure match – any session is fine for darks
            for p, s, et in candidates:
                if _exptime_key(et) == target_key:
                    scope = ('this session' if s == session
                             else f'session {s}')
                    self._log(
                        f'    Using master dark {p.name}'
                        f'  (exact exposure, from {scope})',
                        LogColor.BLUE)
                    return _qflag('-dark', p)

            # 2. Closest exposure overall – warn if delta is large
            candidates.sort(key=lambda pse: abs(pse[2] - exptime))
            best_p, best_s, best_et = candidates[0]
            best_delta = abs(best_et - exptime)
            large = exptime > 0 and (best_delta / exptime) > 0.05
            color = LogColor.SALMON if large else LogColor.BLUE
            tag   = '⚠ ' if large else ''
            self._log(
                f'    {tag}Using closest-exposure dark {best_p.name}'
                f'  (from session {best_s}, ΔEXPTIME={best_delta:.2f}s,'
                f' target={exptime:.0f}s)',
                color)
            return _qflag('-dark', best_p)

        # 3. Legacy generic name (no exptime suffix)
        for ext in FITS_EXTS:
            p = self.masters_dir / f'master-dark_{session}{ext}'
            if p.exists():
                return _qflag('-dark', p)

        # 4. External dark masters folder – closest EXPTIME match
        if self.external_darks and self.external_darks.is_dir() and exptime is not None:
            best_path, best_delta = None, float('inf')
            for f in self.external_darks.rglob('*'):
                if not is_fits_file(f):
                    continue
                try:
                    with astrofits.open(f, memmap=True,
                                        ignore_missing_simple=True) as hdul:
                        h = _find_image_header(hdul)
                        # Reject darks from a different camera
                        dark_instr = str(h.get('INSTRUME', '')).strip()
                        if self.instrument and dark_instr and \
                                dark_instr != self.instrument:
                            self._log(
                                f'    ⚠ Skipping {f.name}: INSTRUME mismatch '
                                f'({dark_instr!r} ≠ {self.instrument!r})',
                                LogColor.SALMON)
                            continue
                        et = h.get('EXPTIME', h.get('EXPOSURE', None))
                        if et is None:
                            continue
                        delta = abs(float(et) - exptime)
                        if delta < best_delta:
                            best_path, best_delta = f, delta
                except Exception:
                    pass
            if best_path is not None:
                self._log(f'    Using external dark {best_path.name}'
                          f'  (ΔEXPTIME={best_delta:.2f}s)', LogColor.BLUE)
                return _qflag('-dark', best_path)
            elif self.instrument:
                self._log(
                    f'    ⚠ No compatible external dark found for '
                    f'instrument {self.instrument!r}',
                    LogColor.SALMON)
        return None

    def _flat_arg(self, session: str, filt_safe: str) -> Optional[str]:
        # Exact match for this session
        for ext in FITS_EXTS:
            p = self.masters_dir / f'master-flat-{filt_safe}_{session}{ext}'
            if p.exists():
                return _qflag('-flat', p)
        # Nearest-flat fallback: find the closest session that has a flat
        # for the same filter (requires use_nearest_flat option)
        if not self.use_nearest_flat:
            return None
        try:
            from datetime import date as _date
            sess_date = _date.fromisoformat(session)
        except ValueError:
            return None
        best_path:  Optional[Path] = None
        best_delta: int            = 10 ** 9
        # Scan all master-flat files in masters_dir and read their DATE-OBS
        # from the FITS header – never parse filenames.
        for ext in FITS_EXTS:
            for p in self.masters_dir.glob(f'master-flat-{filt_safe}*{ext}'):
                if p == (self.masters_dir / f'master-flat-{filt_safe}_{session}{ext}'):
                    continue  # already checked above
                try:
                    with astrofits.open(p, memmap=True,
                                        ignore_missing_simple=True) as hdul:
                        h = _find_image_header(hdul)
                        dobs = str(h.get('DATE-OBS', '')).strip()
                        if not dobs:
                            continue
                        flat_date = _date.fromisoformat(
                            night_key(dobs))  # noon-to-noon key
                except Exception:
                    continue
                delta = abs((flat_date - sess_date).days)
                if delta < best_delta:
                    best_delta, best_path = delta, p
        if best_path is not None:
            self._log(
                f'    Using nearest flat for filter {filt_safe}: '
                f'{best_path.name}  (Δ{best_delta}d)',
                LogColor.BLUE)
            return _qflag('-flat', best_path)
        return None

    # ── Pipeline phases ───────────────────────────────────────────────────────

    def _phase_bias(self):
        """
        Build a master bias (if needed) and place it in masters_dir.
        The bias is camera-wide, not per-session:
          – User-dropped master → copy it in.
          – Bias subs (any session) → stack them all.
          – Synthetic / none → nothing to do here.
        """
        self._log('━━ Phase 1 – Master Bias ━━', LogColor.GREEN)

        # Already present from a previous phase or prior run
        existing = list(self.masters_dir.glob('master-bias*'))
        existing = [p for p in existing if is_fits_file(p)]
        if existing:
            self._log(f'  Master bias already present: {existing[0].name}',
                      LogColor.BLUE)
            return

        # User-dropped pre-existing master bias (take first found, any session)
        pre_bias = next(
            (fi for fi in self._pre_masters if fi['imgtype'] == 'bias'),
            None
        )
        if pre_bias:
            self._ensure_master_in_dir(pre_bias['path'], 'master-bias.fit')
            self._log(f'  Using existing master bias: {pre_bias["path"].name}',
                      LogColor.GREEN)
            return

        # Stack all bias subs from all sessions into one master
        bias_files: list[dict] = []
        for session in self.sessions:
            for bucket in self._by[session]['bias'].values():
                bias_files.extend(bucket)

        if not bias_files:
            if self.synthetic_bias:
                self._log(
                    f'  No bias subs – synthetic bias will be used: {self.synthetic_bias}',
                    LogColor.BLUE)
            else:
                self._log('  No bias subs and no synthetic bias → skipped',
                          LogColor.SALMON)
            return

        seq_dir = self.proc_dir / 'bias_all'
        self._copy_files(bias_files, seq_dir)
        self._cd(seq_dir)
        self.siril.cmd('convert', 'bias_')
        out = self._master_path('master-bias')
        self._stack('bias_', out, n_frames=len(bias_files))
        self._log(f'  ✓ master-bias.fit  ({len(bias_files)} frames total)',
                  LogColor.GREEN)
        self._save_master_if_needed(out.with_suffix('.fit'), 'bias', session='all')
        self._cleanup(seq_dir)


    def _phase_darks(self):
        """
        Build per-exposure master darks for each session.

          – User-dropped pre-masters: each is copied into masters_dir under
            its own canonical name master-dark_{session}_{exp_key}.fit, so
            multiple pre-masters per session (different exposures) are all
            preserved.  Their exptime comes straight from the FITS header.
          – Raw dark subs: grouped by exposure time and stacked one master
            per group.  Exposures already covered by a pre-master are not
            re-stacked.  Exposures that are not in req_exposures (i.e. not
            needed by any light or flat) are skipped to save processing.
          – No darks at all → log and rely on external folder if configured.
        """
        self._log('━━ Phase 2 – Master Darks ━━', LogColor.GREEN)
        _, req_exposures = self._get_active_requirements()

        for session in self.sessions:
            # 1. Import every user-dropped pre-existing master dark for this
            #    session, one per exposure time.  Naming follows the canonical
            #    per-exptime pattern so _dark_arg can match them by exposure.
            imported_exps: set[str] = set()
            for fi in self._pre_masters:
                if fi['imgtype'] != 'dark' or fi['session'] != session:
                    continue
                exp_key  = _exptime_key(fi.get('exptime'))
                exp_stem = f'master-dark_{session}_{exp_key}'
                dest_p   = self.masters_dir / f'{exp_stem}.fit'
                if not dest_p.exists():
                    self._ensure_master_in_dir(fi['path'], exp_stem + '.fit')
                    self._log(
                        f'  [{session}] Using existing master dark: '
                        f'{fi["path"].name}  (exptime={exp_key})',
                        LogColor.GREEN)
                imported_exps.add(exp_key)

            # 2. Stack raw dark subs grouped by exposure time.
            all_dark_files: list[dict] = []
            for bucket in self._by[session]['dark'].values():
                all_dark_files.extend(bucket)

            if not all_dark_files:
                if not imported_exps:
                    msg = ('external folder will be used'
                           if self.external_darks
                           else 'no external folder → skipped')
                    self._log(f'  [{session}] No dark subs – {msg}',
                              LogColor.SALMON)
                continue

            by_exptime: dict = defaultdict(list)
            for fi in all_dark_files:
                by_exptime[_exptime_key(fi.get('exptime'))].append(fi)

            for exp_key, dark_files in sorted(by_exptime.items(),
                                              key=lambda kv: _exptime_sort_key(kv[0])):
                # Pre-existing master at this exposure already wins.
                if exp_key in imported_exps:
                    self._log(
                        f'  [{session}] Skipping raw {exp_key} darks: '
                        f'pre-existing master already in place',
                        LogColor.BLUE)
                    continue
                if exp_key not in req_exposures:
                    self._log(
                        f'  [{session}] Skipping unused Dark exposure: {exp_key}',
                        LogColor.SALMON)
                    continue
                exp_stem = f'master-dark_{session}_{exp_key}'  # e.g. master-dark_2026-03-22_600s
                seq_dir  = self.proc_dir / f'session_{session}' / f'dark_{exp_key}'
                self._copy_files(dark_files, seq_dir)
                self._cd(seq_dir)
                self.siril.cmd('convert', 'dark_')
                out = self._master_path(exp_stem)
                self._stack('dark_', out, n_frames=len(dark_files))
                self._log(f'  [{session}] ✓ {exp_stem}.fit  '
                          f'({len(dark_files)} frames, exptime={exp_key})',
                          LogColor.GREEN)
                self._save_master_if_needed(
                    out.with_suffix('.fit'), 'dark',
                    session=session, exptime=exp_key)
                self._cleanup(seq_dir)

    def _phase_flats(self):
        self._log('━━ Phase 3 – Master Flats ━━', LogColor.GREEN)
        req_filters, _ = self._get_active_requirements()
        for session in self.sessions:
            bias_arg = self._bias_arg()
            if not bias_arg:
                self._log(f'  [{session}] No bias available for flat calibration',
                          LogColor.SALMON)

            # Register user-dropped master flats into masters_dir.
            # - Same-session masters: always copied (exact match for _flat_arg).
            # - Other-session masters: copied when use_nearest_flat is on so
            #   _flat_arg can find them by DATE-OBS and pick the closest one.
            for fi in self._pre_masters:
                if fi['imgtype'] != 'flat':
                    continue
                same_session = (fi['session'] == session)
                if not same_session and not self.use_nearest_flat:
                    continue  # only import cross-session flats when option is on
                filt_safe_pre = _safe_name(fi['filter'])
                # Always name by the master's own session so _flat_arg
                # can compare DATE-OBS values across sessions.
                dest_stem_pre = f'master-flat-{filt_safe_pre}_{fi["session"]}'
                dest_pre = self.masters_dir / f'{dest_stem_pre}.fit'
                if not dest_pre.exists():
                    self._ensure_master_in_dir(fi['path'], dest_stem_pre + '.fit')
                    tag = '' if same_session else f' (cross-session from {fi["session"]})'
                    self._log(f'  [{session}] filter={fi["filter"]}{tag} – '
                              f'using existing master flat: {fi["path"].name}',
                              LogColor.GREEN)

            for filt, flat_files in self._by[session]['flat'].items():
                if not flat_files:
                    continue
                if filt not in req_filters:
                    self._log(f'  [{session}] Skipping unused flat filter: {filt}',
                              LogColor.SALMON)
                    continue
                filt_safe  = _safe_name(filt)
                dest_stem  = f'master-flat-{filt_safe}_{session}'

                # Prefer user-dropped master flat
                pre = self._find_pre_master('flat', session, filt)
                if pre:
                    self._ensure_master_in_dir(pre, dest_stem + '.fit')
                    self._log(f'  [{session}] filter={filt} – '
                              f'using existing master flat: {pre.name}',
                              LogColor.GREEN)
                    continue

                # Determine bias to use for flat calibration.
                # If no real bias exists, look for a dark-flat (a dark whose
                # exptime matches the flat exptime) to use as -bias= instead.
                flat_exptime = next(
                    (fi['exptime'] for fi in flat_files if fi.get('exptime') is not None),
                    None
                )
                cal_bias_arg = bias_arg or self._dark_flat_arg(flat_exptime)
                if cal_bias_arg and not bias_arg:
                    self._log(
                        f'  [{session}] filter={filt}: no bias – '
                        f'using dark flat as bias substitute',
                        LogColor.BLUE)

                seq_dir = self.proc_dir / f'session_{session}' / f'flat_{filt_safe}'
                self._copy_files(flat_files, seq_dir)
                self._cd(seq_dir)
                seq = f'flat_{filt_safe}_'
                self.siril.cmd('convert', seq)
                # Calibrate flats with bias (or dark-flat substitute)
                cal_args = ['calibrate', seq]
                if cal_bias_arg:
                    cal_args.append(cal_bias_arg)
                self.siril.cmd(*cal_args)
                out = self._master_path(dest_stem)
                self._stack(f'pp_{seq}', out, norm='-norm=mul', n_frames=len(flat_files))
                self._log(f'  [{session}] ✓ {dest_stem}.fit  '
                          f'filter={filt}  ({len(flat_files)} frames)',
                          LogColor.GREEN)
                self._save_master_if_needed(
                    out.with_suffix('.fit'), 'flat',
                    session=session, filt=filt)
                # Track master flat path for drizzle -flat= argument
                for ext in FITS_EXTS:
                    mp = out.parent / f'{out.name}{ext}'
                    if mp.exists():
                        self._master_flats[filt_safe] = mp
                        break
                self._cleanup(seq_dir)

    def _phase_lights(self):
        """
        Calibrate lights grouped by (filter, exptime).

        Each group gets its own sequence: light_FILTER_EXPs_
        so that HDR sets with different exposure times are kept separate
        all the way through registration and stacking.

        Decision matrix (bias/dark/flat availability → calibrate args):
          bias  dark  flat  → -dark= -flat=              dark absorbs bias
          bias  dark  –     → -dark=                     dark absorbs bias
          bias  –     flat  → -bias= -flat=              bias as dark
          bias  –     –     → -bias=                     bias as dark only
          –     dark  [flat]→ -dark= [-flat=]            dark [+flat]
          –     –     flat  → -flat=                     flat only
          –     –     –     → (no masters)

        IMPORTANT: when a dark is available, -bias= is NEVER passed to
        calibrate for lights.  The dark already contains the bias signal.
        Passing both would double-subtract the bias.
        The bias is only used to calibrate flats (in _phase_flats).

        Debayer: -debayer added when any sub in the group carries BAYERPAT.
        """
        self._log('━━ Phase 4 – Calibrate Lights ━━', LogColor.GREEN)
        for session in self.sessions:
            bias_arg = self._bias_arg()

            for filt, all_light_files in self._by[session]['light'].items():
                if not all_light_files:
                    continue
                filt_safe = _safe_name(filt)
                flat_arg  = self._flat_arg(session, filt_safe)

                # Sub-group by exptime for HDR support
                by_exptime: dict = defaultdict(list)
                for fi in all_light_files:
                    by_exptime[_exptime_key(fi.get('exptime'))].append(fi)

                for exp_key, light_files in sorted(by_exptime.items()):
                    obj_safe   = _safe_name(
                        (light_files[0].get('object_name') or 'unknown')
                        if light_files else 'unknown')
                    group_safe = f'{obj_safe}_{filt_safe}_{exp_key}'  # e.g. M106_Ha_600s

                    # Representative float exptime for dark matching
                    exptimes = [fi['exptime'] for fi in light_files
                                if fi.get('exptime') is not None]
                    exptime  = (float(max(set(exptimes), key=exptimes.count))
                                if exptimes else None)

                    dark_arg = self._dark_arg(session, exptime)

                    has_bias = bias_arg is not None
                    has_dark = dark_arg is not None
                    has_flat = flat_arg is not None
                    is_cfa   = any(fi.get('bayerpat') for fi in light_files)

                    seq = f'light_{group_safe}_'
                    cal_args = ['calibrate', seq]

                    if has_dark:
                        # Dark already contains bias – never pass -bias= to
                        # calibrate when a dark is available.
                        cal_args.append(dark_arg)
                        if has_flat:
                            cal_args.append(flat_arg)
                        mode = f'dark{("+flat" if has_flat else " only")}'
                    elif has_bias and has_flat:
                        # No dark: use bias as pedestal correction.
                        cal_args += [bias_arg, flat_arg]
                        mode = 'bias-as-dark+flat'
                    elif has_bias:
                        cal_args.append(bias_arg)
                        mode = 'bias-as-dark only'
                    elif has_flat:
                        cal_args.append(flat_arg)
                        mode = 'flat only'
                    else:
                        mode = 'no masters'

                    if is_cfa:
                        # -cfa : sequence is Bayer
                        cal_args.append('-cfa')

                        if has_flat:
                            # Normalize each CFA channel only if flats are used
                            cal_args.append('-equalize_cfa')

                        if has_dark:
                            # Cosmetic correction only if a dark is available
                            cal_args.append('-cc=dark')

                        if not self.use_drizzle:
                            # Debayer only if we are not doing drizzle
                            cal_args.append('-debayer')

                    seq_dir = (self.proc_dir / f'session_{session}'
                               / f'light_{group_safe}')
                    self._copy_files(light_files, seq_dir)
                    self._cd(seq_dir)
                    self.siril.cmd('convert', seq)
                    self.siril.cmd(*cal_args)
                    self._log(
                        f'  [{session}] ✓ {filt}/{exp_key}  mode={mode}'
                        f'{"  debayer" if is_cfa else ""}'
                        f'  ({len(light_files)} frames)',
                        LogColor.GREEN,
                    )

    def _phase_register_stack(self) -> dict[str, list[Path]]:
        """
        Per (filter, exptime) group:
          1. Collect pp_light_FILTER_EXPs sequences across sessions.
          2. Merge if multiple sessions (Siril `merge`), or use directly.
          3. register -2pass  +  seqapplyreg -framing=current
          4. stack → stacked_FILTER_EXPs.fit  (absolute path)
          5. load, mirrorx -bottomup, save with keyword-token pattern.

        Returns the list of saved stack Paths (for cross-stack alignment).
        Cleanup of _preproc happens after alignment in run().
        """
        self._log('━━ Phase 5 – Register & Stack ━━', LogColor.GREEN)

        # Build the set of (filter, exptime_key) groups across all sessions
        all_groups: set = set()
        for session in self.sessions:
            for filt, files in self._by[session]['light'].items():
                for fi in files:
                    obj = fi.get('object_name') or 'unknown'
                    all_groups.add((obj, filt, _exptime_key(fi.get('exptime'))))

        saved_stacks: dict[str, list[Path]] = defaultdict(list)

        for obj, filt, exp_key in sorted(all_groups):
            obj_safe      = _safe_name(obj)
            filt_safe     = _safe_name(filt)
            group_safe    = f'{obj_safe}_{filt_safe}_{exp_key}'  # e.g. M106_Ha_600s
            seq_base      = f'light_{group_safe}_'    # sequence produced by calibrate

            # Gather per-session dirs that have this (object, filter, exptime) group
            session_seq_dirs: list[Path] = []
            total_frames = 0
            for session in self.sessions:
                if filt not in self._by[session]['light']:
                    continue
                # Count files in this session matching this object+exptime
                n = sum(
                    1 for fi in self._by[session]['light'][filt]
                    if _exptime_key(fi.get('exptime')) == exp_key
                    and (fi.get('object_name') or 'unknown') == obj
                )
                if n == 0:
                    continue
                sess_light_dir = (self.proc_dir / f'session_{session}'
                                  / f'light_{group_safe}')
                seq_file = sess_light_dir / f'pp_{seq_base}.seq'
                if sess_light_dir.is_dir() and seq_file.exists():
                    session_seq_dirs.append(sess_light_dir)
                    total_frames += n
                else:
                    self._log(
                        f'  [{session}] {filt}/{exp_key}: sequence not found'
                        f' ({seq_file}) – skipped', LogColor.SALMON)

            if not session_seq_dirs:
                self._log(
                    f'  {filt}/{exp_key}: no calibrated sequences – skipped',
                    LogColor.SALMON)
                continue

            self._log(
                f'  {obj}/{filt}/{exp_key}: {len(session_seq_dirs)} session(s),'
                f' {total_frames} frame(s)', LogColor.BLUE)

            process_dir = self.proc_dir / f'process_{group_safe}'
            process_dir.mkdir(parents=True, exist_ok=True)

            pp_seq       = f'pp_{seq_base}'
            merged_seq   = f'merged_{group_safe}_'
            register_seq = merged_seq
            self._cd(process_dir)

            if len(session_seq_dirs) == 1:
                self._cd(session_seq_dirs[0])
                register_seq = pp_seq
                self._log(f'  {obj}/{filt}/{exp_key}: single session, no merge',
                          LogColor.BLUE)
            else:
                seq_args = [
                    _qarg(d / pp_seq)
                    for d in session_seq_dirs
                ]
                self.siril.cmd('merge', *seq_args, merged_seq)
                self._log(
                    f'  {obj}/{filt}/{exp_key}: merged {len(session_seq_dirs)}'
                    f' sequences → {merged_seq}', LogColor.GREEN)

            # ── Optional background extraction ────────────────────────────
            if self.use_bkg:
                self.siril.cmd('seqsubsky', register_seq, '1')
                register_seq = f'bkg_{register_seq}'
                self._log(f'  {obj}/{filt}/{exp_key}: background extracted → {register_seq}',
                          LogColor.BLUE)

            # ── Plate-solve for distortion model (if requested) ───────────
            wcs_file = None
            if self.use_disto:
                ref_frame = f'{register_seq}00001'
                wcs_file  = 'platesolve_data.wcs'
                self.siril.cmd('load', ref_frame)
                self.siril.cmd('parse', '$RA:ra$_$DEC:dec$')
                self.siril.cmd('platesolve', '-force', f'-disto={wcs_file}')
                self._log(f'  {obj}/{filt}/{exp_key}: plate-solve done → {wcs_file}',
                          LogColor.BLUE)

            # ── Register ─────────────────────────────────────────────────
            # Determine if frames are CFA (any sub in this group has bayerpat)
            is_cfa = any(
                fi.get('bayerpat')
                for session in self.sessions
                for fi in self._by.get(session, {}).get('light', {}).get(filt, [])
                if _exptime_key(fi.get('exptime')) == exp_key
                and (fi.get('object_name') or 'unknown') == obj
            )

            # Register – always called; distortion args added when available
            reg_args = ['register', register_seq, '-2pass']
            if wcs_file:
                reg_args += ['-disto=file', wcs_file]
            self.siril.cmd(*reg_args)

            if self.use_drizzle:
                seqapplyreg_args = [
                    'seqapplyreg', register_seq, '-framing=current',
                    '-drizzle',
                    f'-scale={self.drizzle_scale:.1f}',
                    f'-pixfrac={self.drizzle_pixfrac:.2f}',
                    '-kernel=square',
                ]
                mf = self._master_flats.get(filt_safe)
                if mf and mf.exists():
                    seqapplyreg_args.append(_qflag('-flat', mf))
                self.siril.cmd(*seqapplyreg_args)
                mode_str = (
                    f'drizzle (scale={self.drizzle_scale}, '
                    f'pixfrac={self.drizzle_pixfrac})'
                )
                if is_cfa:
                    mode_str += '  [Bayer Drizzle]'
                self._log(f'  {obj}/{filt}/{exp_key}: {mode_str}', LogColor.BLUE)
                # register -drizzle writes r_<seq> directly in the cwd;
                # no extra copy or convert needed.
                r_seq = f'r_{register_seq}'
            else:
                self.siril.cmd('seqapplyreg', register_seq, '-framing=current')
                r_seq = f'r_{register_seq}'

            # Stack – ensure cwd matches where r_seq was produced.
            # Single session: r_seq lives in the session dir (both drizzle
            # and standard seqapplyreg write their output there).
            # Multi-session: r_seq lives in process_dir (after merge).
            stacked_abs = (process_dir / f'stacked_{group_safe}').resolve()
            if len(session_seq_dirs) == 1:
                self._cd(session_seq_dirs[0])
            else:
                self._cd(process_dir)
            algo, sig_lo, sig_hi = self._rejection_params(total_frames)
            self._log(
                f'  {obj}/{filt}/{exp_key}: rejection={algo}'
                f' ({sig_lo}/{sig_hi})', LogColor.BLUE)
            self.siril.cmd(
                'stack', r_seq,
                'rej', algo, sig_lo, sig_hi,
                '-norm=addscale',
                '-output_norm',
                '-32b',
                '-rgb_equal',
                _qflag('-out', stacked_abs),
            )

            # Save the stack to output_dir with the canonical name pattern.
            # Record the modification time just before saving so we can
            # identify the saved file even if it already existed (re-run).
            t_before = _time.time()
            self._cd(self.output_dir)
            self.siril.cmd('load', _qarg(stacked_abs))
            self.siril.cmd('mirrorx', '-bottomup')
            self.siril.cmd('save', STACK_SAVE_PATTERN)
            # Collect files written or overwritten since t_before
            new_files = sorted(
                f for f in self.output_dir.iterdir()
                if f.is_file() and is_fits_file(f)
                and f.stat().st_mtime >= t_before - 1.0
            )
            if new_files:
                saved_stacks[obj].append(new_files[0])
                self._log(
                    f'  {obj}/{filt}/{exp_key}: ✓ → {new_files[0].name}',
                    LogColor.GREEN)
            else:
                self._log(
                    f'  {obj}/{filt}/{exp_key}: ⚠ could not identify saved file',
                    LogColor.SALMON)

            # Stack is saved to output_dir – free the working dirs for this group
            self._cleanup(process_dir)
            for _sess in self.sessions:
                self._cleanup(
                    self.proc_dir / f'session_{_sess}' / f'light_{group_safe}'
                )

        return saved_stacks

    def _phase_align_stacks(self, stacks_by_obj: dict):
        """
        Align stacks within each object separately.
        stacks_by_obj: dict mapping object name → list of saved stack Paths.
        Objects with only one stack are skipped (nothing to align).
        """
        self._log('━━ Phase 6 – Cross-stack Alignment ━━', LogColor.GREEN)

        def _align_group(obj_name: str, stack_files: list[Path], tmp_suffix: str):
            """Align a list of stacks and write aligned_* files to output_dir."""
            self._log(
                f'  [{obj_name}] {len(stack_files)} stack(s): '
                + ', '.join(f.name for f in stack_files),
                LogColor.BLUE)

            if len(stack_files) < 2:
                self._log(f'  [{obj_name}] Only one stack – skipped.',
                          LogColor.BLUE)
                return

            tmp_dir = self.proc_dir / f'_align_tmp{tmp_suffix}'
            tmp_dir.mkdir(parents=True, exist_ok=True)

            ordered = sorted(stack_files, key=lambda f: f.name)
            for src in ordered:
                dst = tmp_dir / src.name
                if not dst.exists():
                    shutil.copy2(str(src), str(dst))

            self._cd(tmp_dir)
            tmp_seq = 'align_tmp_'
            self.siril.cmd('convert', tmp_seq)
            self.siril.cmd('register', tmp_seq, '-2pass')
            self.siril.cmd('seqapplyreg', tmp_seq, '-framing=min')

            registered = sorted(
                f for f in tmp_dir.iterdir()
                if f.is_file() and f.name.startswith('r_align_tmp_') and is_fits_file(f)
            )

            if len(registered) != len(ordered):
                self._log(
                    f'  [{obj_name}] ⚠ Expected {len(ordered)} registered, '
                    f'got {len(registered)} – alignment may be incomplete.',
                    LogColor.SALMON)

            for r_file, original in zip(registered, ordered):
                self._cd(self.output_dir)
                self.siril.cmd('load', str(r_file))
                self.siril.cmd('save', 'aligned_' + STACK_SAVE_PATTERN)

            self._cleanup(tmp_dir)
            self._log(f'  [{obj_name}] ✓ Cross-alignment done.', LogColor.GREEN)

        total_objs = len(stacks_by_obj)
        self._log(
            f'  Received stacks for {total_objs} object(s): '
            + ', '.join(stacks_by_obj.keys()),
            LogColor.BLUE)

        for i, (obj_name, stack_files) in enumerate(sorted(stacks_by_obj.items())):
            _align_group(obj_name, stack_files, f'_{i}')


    # ── Public entry point ────────────────────────────────────────────────────

    def run(self):
        # Determine a safe return directory:
        # - self.wd comes from siril.get_siril_wd() at engine-creation time.
        # - If a previous run crashed inside _preproc, get_siril_wd() may
        #   return a deleted sub-folder.  Validate it and fall back to
        #   output_dir (which we are about to create) if necessary.
        candidate_wd = self.wd
        if (not candidate_wd.exists()
                or self.proc_dir in candidate_wd.parents
                or candidate_wd == self.proc_dir):
            candidate_wd = self.output_dir
        original_wd = candidate_wd

        # proc_dir is a fresh mkdtemp() directory – always clean.
        self.masters_dir.mkdir(parents=True, exist_ok=True)
        self.output_dir.mkdir(parents=True, exist_ok=True)

        try:
            linear_phases = [
                self._phase_bias,
                self._phase_darks,
                self._phase_flats,
                self._phase_lights,
            ]
            for i, fn in enumerate(linear_phases):
                if self.progress_cb:
                    self.progress_cb(i + 1, N_PHASES, PHASE_LABELS[i])
                fn()

            # Masters are only needed for phase 4 (calibrate lights).
            # Delete them now to free space before the heavier register/stack phase.
            self._cleanup(self.masters_dir)

            # Phase 5: register & stack – returns the list of saved stack paths
            if self.progress_cb:
                self.progress_cb(5, N_PHASES, PHASE_LABELS[4])
            saved_stacks = self._phase_register_stack()

            # Phase 6: cross-stack alignment (needs the exact file list from phase 5)
            if self.progress_cb:
                self.progress_cb(6, N_PHASES, PHASE_LABELS[5])
            self._phase_align_stacks(dict(saved_stacks))

            self._log('━━ Pre-processing complete! ━━', LogColor.GREEN)

        finally:
            # Always executed: restore WD and delete _preproc.
            # This runs even if an error interrupted the pipeline.
            try:
                _rp = str(original_wd.resolve())
                self.siril.cmd(f'cd "{_rp}"' if ' ' in _rp else f'cd {_rp}')
                self._log(f'↩  Returned to working directory: {original_wd}',
                          LogColor.BLUE)
            except Exception:
                pass
            try:
                if self.proc_dir.is_dir():
                    shutil.rmtree(str(self.proc_dir), ignore_errors=True)
                    self._log('  _preproc directory removed.', LogColor.BLUE)
            except Exception:
                pass


# =============================================================================
# Processing worker thread (keeps UI responsive)
# =============================================================================

class ProcessingWorker(QThread):
    """
    Runs the PreprocessingEngine in a background thread so the Qt event
    loop stays alive and the UI remains responsive.

    NOTE: All siril.cmd() / siril.log() calls happen exclusively in this
    thread while it is running.  The main thread must NOT call siril.log()
    until finished() has been received.
    """
    phase_changed = pyqtSignal(int, int, str)   # (phase_idx, total, label)
    finished      = pyqtSignal(bool, str)        # (success, message)

    def __init__(self, engine: PreprocessingEngine):
        super().__init__()
        self.engine = engine

    def run(self):
        def _progress(phase: int, total: int, label: str):
            self.phase_changed.emit(phase, total, label)

        self.engine.progress_cb = _progress
        try:
            self.engine.run()
            self.finished.emit(True, 'Pre-processing complete!')
        except (s.CommandError, s.DataError, s.SirilError) as e:
            msg = f'Siril error: {e}'
            try:
                self.engine.siril.log(msg, LogColor.RED)
            except Exception:
                pass
            self.finished.emit(False, msg)
        except Exception as e:
            import traceback
            traceback.print_exc()
            msg = f'Unexpected error: {e}'
            try:
                self.engine.siril.log(msg, LogColor.RED)
            except Exception:
                pass
            self.finished.emit(False, msg)


# =============================================================================
# Drop zone widget
# =============================================================================

class DropZone(QFrame):
    files_dropped = pyqtSignal(list)

    _IDLE = ('DropZone { border: 2px dashed #555555; border-radius: 14px;'
             ' background-color: #1a1a2e; } QLabel { color: #dddddd; }')
    _HOVER = ('DropZone { border: 2px dashed #5BA3FF; border-radius: 14px;'
              ' background-color: #1a2640; } QLabel { color: #ffffff; }')

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAcceptDrops(True)
        self.setMinimumHeight(100)
        self.setStyleSheet(self._IDLE)
        lay = QVBoxLayout(self)
        lay.setAlignment(Qt.AlignmentFlag.AlignCenter)
        lay.setSpacing(4)
        icon  = QLabel('📂'); icon.setAlignment(Qt.AlignmentFlag.AlignCenter)
        fi = QFont(); fi.setPointSize(24); icon.setFont(fi)
        title = QLabel('Drop FITS files or folders here')
        title.setAlignment(Qt.AlignmentFlag.AlignCenter)
        ft = QFont(); ft.setPointSize(11); ft.setBold(True); title.setFont(ft)
        sub = QLabel('Accepted: .fits  .fit  .fts  .fits.fz  (any case)')
        sub.setAlignment(Qt.AlignmentFlag.AlignCenter)
        fs = QFont(); fs.setPointSize(8); sub.setFont(fs)
        sub.setStyleSheet('color: #666666;')
        lay.addWidget(icon); lay.addWidget(title); lay.addWidget(sub)

    def dragEnterEvent(self, event: QDragEnterEvent):
        if event.mimeData().hasUrls():
            paths = [u.toLocalFile() for u in event.mimeData().urls()]
            if any(Path(p).is_dir() or is_fits_file(Path(p)) for p in paths):
                event.acceptProposedAction()
                self.setStyleSheet(self._HOVER)
                return
        event.ignore()

    def dragLeaveEvent(self, event):
        self.setStyleSheet(self._IDLE)

    def dropEvent(self, event: QDropEvent):
        self.setStyleSheet(self._IDLE)
        self.files_dropped.emit([u.toLocalFile() for u in event.mimeData().urls()])


