        btn_darks = QPushButton('Browse…'); btn_darks.setFixedHeight(24)
        btn_darks.clicked.connect(self._browse_darks)
        opts_lay.addWidget(btn_darks)
        btn_darks_clear = QPushButton('✕'); btn_darks_clear.setFixedSize(24, 24)
        btn_darks_clear.setToolTip('Clear external darks')
        btn_darks_clear.setStyleSheet(
            'QPushButton { color:#aa4444; border:1px solid #553333;'
            ' border-radius:4px; background:#1a1a2e; }'
            'QPushButton:hover { background:#2a1a1a; }'
        )
        btn_darks_clear.clicked.connect(self._clear_darks)
        opts_lay.addWidget(btn_darks_clear)

        opts_lay.addSpacing(12)

        # Output directory
        opts_lay.addWidget(_row('Output dir:',
                                'Where final stacked images will be saved.\n'
                                'Defaults to the Siril working directory.'))
        self._out_lbl = QLabel('(Siril working directory)')
        self._out_lbl.setStyleSheet('color:#666666; font-size:9pt; border:none;')
        self._out_lbl.setSizePolicy(QSizePolicy.Policy.Expanding,
                                    QSizePolicy.Policy.Preferred)
        opts_lay.addWidget(self._out_lbl)
        btn_out = QPushButton('Browse…'); btn_out.setFixedHeight(24)
